    result_summary: ft ? FORMULA_TESTS[2] : '', next_action: ft ? FORMULA_TESTS[3] : '',
    estimated_source_cost_usd: ft ? NEGATIVE_TESTS[0] : '', estimated_analysis_cost_usd: ft ? NEGATIVE_TESTS[1] : '',
